const svgAssets={home:'home-2-svgrepo-com.svg',search:'search-magnifier-ui-svgrepo-com.svg',shopping_bag:'shopping-bag-svgrepo-com.svg',inventory_2:'order-svgrepo-com.svg',receipt_long:'order-svgrepo-com.svg',person:'user-profile-avatar-svgrepo-com.svg',notifications:'bell-ui-notification-svgrepo-com.svg',location_on:'place-ui-pin-svgrepo-com.svg',favorite:'love-ui-heart-svgrepo-com.svg',recycling:'recycle-svgrepo-com.svg',agriculture:'agriculture-svgrepo-com.svg',local_shipping:'delivery-truck-van-svgrepo-com.svg',shopping_cart:'shopping-basket-svgrepo-com.svg',verified:'verified-check-svgrepo-com.svg',verified_user:'verified-check-svgrepo-com.svg'};
const icon=(name)=>svgAssets[name]?`<img class="symbol svg-asset asset-${name}" src="${svgAssets[name]}" alt="" aria-hidden="true">`:`<svg class="symbol" viewBox="0 0 24 24" aria-hidden="true" focusable="false" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${iconPaths[name]||iconPaths.eco}</svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const userAvatar=()=>db.user?.photo?`<img class="avatar-image" src="${db.user.photo}" alt="${esc(db.user.name)}">`:esc(db.user?.avatar||'👩🏽‍🌾');
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(window._toast);window._toast=setTimeout(()=>t.classList.remove('show'),2600)}
function go(route){location.hash=route;render()}
function login(role){db.role=role;db.user=role==='staff'?{name:'Amina N.',title:'Operations manager',avatar:'👩🏽‍💼'}:{name:'Christine',title:'BSF farmer · Wakiso',avatar:'👩🏽‍🌾'};save();go(role==='staff'?'staff':'home');toast(`Welcome ${db.user.name.split(' ')[0]}!`)}
const route=()=>location.hash.replace(/^#\/?/,'')|| (db.role==='staff'?'staff':db.role?'home':'login');
function brand(){return `<div class="brand"><div class="brand-mark"><img class="brand-logo-crop" src="green-divert-africa-logo.png" alt=""></div><div>Green Divert<small>for Africa</small></div></div>`}
function brandLockup(size='auth'){return `<div class="brand-lockup ${size}"><div class="brand-emblem"><img src="green-divert-africa-logo.png" alt=""></div><div class="brand-lockup-name"><strong>The Green Divert</strong><b>for Africa</b></div></div>`}
const farmerNav=[['home','home','Home'],['market','storefront','Marketplace'],['favorites','favorite','Favorites'],['tracking','local_shipping','Track delivery'],['profile','person','My farm']];
const staffNav=[['staff','space_dashboard','Overview'],['inventory','inventory_2','Inventory'],['collection','add_box','Log collection'],['stafforders','receipt_long','Orders'],['agents','groups','Field agents']];
function mobileNavigation(isStaff,active){const items=isStaff?staffNav.slice(0,4):[['home','home','Home'],['market','search','Explore'],['cart','shopping_bag','Order'],['favorites','favorite','Favorites'],['profile','person','Profile']];const cartCount=db.cart.reduce((n,x)=>n+x.qty,0),favoriteCount=(db.favorites||[]).length;return `<nav class="mobile-nav" aria-label="Main navigation">${items.map(([r,i,l])=>{const count=r==='cart'?cartCount:r==='favorites'?favoriteCount:0;return `<button type="button" data-go="${r}" class="${active===r?'active':''} ${r==='cart'?'mobile-cart':''}" ${active===r?'aria-current="page"':''} aria-label="${l}${count?` (${count})`:''}">${r==='cart'?'<img class="nav-bag-svg" src="shopping-bag-svgrepo-com.svg" alt="">':icon(i)}${count?`<i class="nav-count ${r==='cart'?'order-count':'favorite-count'}">${count>99?'99+':count}</i>`:''}<span>${l}</span></button>`}).join('')}</nav>`}
function shell(content){const isStaff=db.role==='staff',nav=isStaff?staffNav:farmerNav;const active=route()==='category'?'home':route().startsWith('product/')?'market':route();app.innerHTML=`<div class="app-shell"><aside class="sidebar">${brand()}<nav class="side-nav">${nav.map(([r,i,l])=>`<button class="side-link ${active===r?'active':''}" data-go="${r}">${icon(i)}${l}</button>`).join('')}</nav><div class="side-bottom"><div class="side-help"><strong>Need a hand?</strong><p>Our team is here to help your farm grow.</p><button class="btn btn-soft btn-block" data-action="help">${icon('support_agent')} Contact support</button></div><div class="profile-mini"><div class="avatar">${userAvatar()}</div><div><strong>${esc(db.user.name)}</strong><small>${esc(db.user.title)}</small></div><button class="icon-btn" style="margin-left:auto" data-action="logout" aria-label="Sign out">${icon('logout')}</button></div></div></aside><main class="main ${!isStaff&&(['home','market','tracking','favorites','cart','profile'].includes(active)||active.startsWith('product/'))?'farmer-mobile-home':' '}"><header class="topbar"><div class="topbar-left"><button class="icon-btn hamburger" data-action="menu">${icon('menu')}</button><span class="mobile-brand">${brand()}</span><strong class="topbar-title">${isStaff?'Operations workspace':'Farmer workspace'}</strong></div><div class="topbar-right"><span class="badge" style="background:#eef8ee">${icon('wifi')} <span>Synced</span></span><button class="icon-btn" data-action="notifications" aria-label="Notifications">${icon('notifications')}</button><button type="button" class="avatar" data-action="logout" aria-label="Sign out" title="Sign out">${userAvatar()}</button></div></header>${content}${mobileNavigation(isStaff,active)}</main></div>`;startPromoCarousel();}
let onboardingStep=0,startupTimer=null;
const onboardingSlides=[{title:'Fresh feedstock for your farm',copy:'Find quality-checked organic waste collected for your BSF operation.'},{title:'Know what is available',copy:'Browse fresh collections from local markets and collection agents.'},{title:'Order and follow delivery',copy:'Place an order and keep up with every update until it reaches your farm.'}];
function renderOnboarding(){const slide=onboardingSlides[onboardingStep];app.innerHTML=`<main class="onboarding-screen"><div class="onboarding-green"><button class="onboarding-skip" data-onboarding="skip">Skip</button><div class="onboarding-farmer" aria-hidden="true"><span class="farmer-orbit orbit-a"></span><span class="farmer-orbit orbit-b"></span><svg class="farmer-memoji" viewBox="0 0 280 330" role="img" aria-label="Smiling farmer in a straw hat"><defs><linearGradient id="farmerShirt" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#63b96b"/><stop offset="1" stop-color="#17693b"/></linearGradient><linearGradient id="farmerHat" x1="0" x2="0" y1="0" y2="1"><stop stop-color="#f8d36c"/><stop offset="1" stop-color="#cc8b32"/></linearGradient></defs><ellipse cx="140" cy="307" rx="87" ry="12" fill="#103c2860"/><path d="M50 305c5-62 37-96 90-96s86 34 90 96z" fill="url(#farmerShirt)"/><path d="M116 207h48v38c-13 15-35 15-48 0z" fill="#75452f"/><path d="M83 115c0-52 25-81 57-81s57 29 57 81v47c0 44-28 70-57 70s-57-26-57-70z" fill="#8e5738"/><path d="M84 129c6-31 20-50 34-59 20 15 45 19 78 15-6-35-29-55-59-55-39 0-65 33-65 86 0 18 4 32 11 45z" fill="#34291f"/><ellipse cx="105" cy="130" rx="8" ry="11" fill="#fff"/><ellipse cx="175" cy="130" rx="8" ry="11" fill="#fff"/><circle cx="107" cy="131" r="4.5" fill="#202820"/><circle cx="177" cy="131" r="4.5" fill="#202820"/><path d="M91 112q14-12 28 0m42 0q14-12 28 0" fill="none" stroke="#422e24" stroke-width="6" stroke-linecap="round"/><path d="M139 134q-2 19-10 27 9 7 19 0" fill="none" stroke="#72432f" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><path d="M116 174q24 24 48 0" fill="none" stroke="#54291f" stroke-width="6" stroke-linecap="round"/><path d="M44 74q8-43 96-43 85 0 96 43-96 29-192 0Z" fill="url(#farmerHat)" stroke="#a9712d" stroke-width="4"/><path d="M64 76q76-23 152 0" fill="none" stroke="#ffe79b" stroke-width="5" stroke-linecap="round"/><path d="M112 216l28 34 28-34" fill="#f3f7e9"/><path d="m119 233 21 17-15 25-22-40m57 0-20 15 15 27 22-42" fill="#f3f7e9"/></svg><span class="farmer-leaf">${icon('agriculture')}</span></div><svg class="onboarding-wave" viewBox="0 0 100 34" preserveAspectRatio="none" aria-hidden="true"><path d="M0 2 Q50 54 100 2 L100 34 L0 34Z" fill="white"/></svg></div><div class="onboarding-content"><div class="onboarding-dots">${onboardingSlides.map((_,i)=>`<button class="${i===onboardingStep?'active':''}" data-onboarding-dot="${i}" aria-label="Page ${i+1}"></button>`).join('')}</div><span class="eyebrow">GREEN DIVERT FOR AFRICA</span><h1>${slide.title}</h1><p>${slide.copy}</p><div class="onboarding-actions">${onboardingStep?`<button class="onboarding-back" data-onboarding="back">${icon('arrow_back')}</button>`:''}<button class="btn btn-primary" data-onboarding="next">${onboardingStep===onboardingSlides.length-1?'Let’s explore':'Continue'} ${icon('arrow_forward')}</button></div></div></main>`}
function finishOnboarding(){try{localStorage.setItem('gdfa-onboarded-v1','1')}catch{}render()}
function startExperience(){const preview=new URLSearchParams(location.search);if(preview.get('login')==='1'){loginPage();return}if(preview.get('welcome')==='1'){onboardingStep=0;renderOnboarding();return}app.innerHTML=`<main class="splash-screen"><div class="splash-orbit splash-orbit-one"></div><div class="splash-orbit splash-orbit-two"></div>${brandLockup('splash')}<p class="splash-tagline">Empowering a greener, cleaner Africa</p><div class="splash-loader"><i></i></div><small>Growing a circular future</small></main>`;clearTimeout(startupTimer);startupTimer=setTimeout(()=>{let completed=false;try{completed=localStorage.getItem('gdfa-onboarded-v1')==='1'}catch{}if(completed)render();else{onboardingStep=0;renderOnboarding()}},1800)}
function loginPage(){app.innerHTML=`<div class="auth"><section class="auth-visual">${brandLockup('auth')}<div class="auth-quote"><div class="eyebrow">A smarter way to grow</div><h1>Waste less.<br>Grow more.</h1><p>Reliable organic feedstock for your BSF farm, sourced from your community and delivered to your door.</p><div class="auth-stat"><div><strong>1,200+</strong><span>farmers growing</span></div><div><strong>8,400t</strong><span>waste diverted</span></div><div><strong>12 districts</strong><span>and growing</span></div></div></div><div class="auth-art">🌱♻️</div><small style="color:#d2e2d2;position:relative">© 2026 Green Divert for Africa</small></section><section class="auth-panel"><div class="auth-form"><span class="eyebrow">Welcome back</span><h2>Good to see you.</h2><p>Sign in to manage your farm supplies and deliveries.</p><form id="login-form" class="auth-fields"><label class="field">Phone number or email<input required placeholder="e.g. +256 700 123 456" autocomplete="username"></label><label class="field">Password<input required type="password" placeholder="Enter your password" autocomplete="current-password"></label><div style="display:flex;justify-content:space-between;align-items:center;font-size:12px"><label><input type="checkbox" checked> Remember me</label><button type="button" class="text-link" data-action="forgot">Forgot password?</button></div><button class="btn btn-primary btn-block" type="submit">Sign in ${icon('arrow_forward')}</button></form><div class="auth-foot">New to Green Divert? <button class="text-link" data-action="signup">Create farmer account</button></div><div class="demo-box"><strong>Explore the live prototype</strong><div class="muted tiny" style="margin-top:3px">Quick access — no password needed</div><div class="demo-actions"><button type="button" class="btn btn-soft" onclick="startDemo('farmer')">👩🏽‍🌾 Farmer demo</button><button type="button" class="btn btn-primary" onclick="startDemo('staff')">🧑🏽‍💼 Staff demo</button></div></div></div></section></div>`}
function stat(label,val,ico,trend){return `<div class="card stat"><div class="stat-top"><span>${label}</span><span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${val}</div><span class="trend">${trend}</span></div>`}
function wasteCard(w){return `<article class="card waste-card"><div class="waste-image ${w.color}" style="background-image:url('${imageFor(w.color)}')"><span class="tag">${icon('verified')} Quality checked</span></div><div class="waste-body"><div class="waste-title"><h3>${esc(w.name)}</h3>${icon('more_horiz')}</div><div class="muted tiny">${esc(w.category)} · ${esc(w.location)}</div><div class="waste-meta"><span>${icon('scale')} ${w.stock.toLocaleString()} kg available</span><span>${icon('schedule')} ${esc(w.fresh)}</span></div><div style="display:flex;align-items:baseline;justify-content:space-between"><span class="price">${money(w.price)}<small> / ${esc(w.unit)}</small></span><span class="badge">In stock</span></div><button class="btn btn-soft btn-block" data-add="${w.id}">${icon('add_shopping_cart')} Add to order</button></div></article>`}
function imageFor(c){const imgs={vegetable:'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=900&q=82',banana:'https://images.unsplash.com/photo-1571771894821-ce9b6c11b08e?auto=format&fit=crop&w=900&q=82',maize:'https://images.unsplash.com/photo-1601593768796-54e1f9f1d080?auto=format&fit=crop&w=900&q=82',pineapple:'https://images.unsplash.com/photo-1550258987-190a2d41a8ba?auto=format&fit=crop&w=900&q=82',coffee:'https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=900&q=82',cassava:'https://images.unsplash.com/photo-1518977676601-b53f82aba655?auto=format&fit=crop&w=900&q=82'};return imgs[c]||imgs.vegetable}
function mobileWasteCard(w){return `<article class="mobile-waste-card"><div class="mobile-waste-image" style="background-image:url('${imageFor(w.color)}')"><span class="mobile-fresh">Fresh</span><button class="mobile-heart ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="${db.favorites.includes(w.id)?'Remove from':'Add to'} favorites">${icon('favorite')}</button></div><div class="mobile-waste-info"><strong>${esc(w.name)}</strong><small>${esc(w.location.split(',')[0])} · ${w.stock.toLocaleString()} kg</small><div class="mobile-price-row"><b>${money(w.price)}</b><span>/ sack</span><button class="mobile-add" data-add="${w.id}" aria-label="Add ${esc(w.name)}">${icon('shopping_bag')}</button></div></div></article>`}
function categoryProductCard(w){return `<article class="category-product-card"><button class="category-product-open" data-go="product/${w.id}" aria-label="View ${esc(w.name)} details"><div class="category-product-image" style="background-image:url('${imageFor(w.color)}')"><span class="category-fresh">Fresh</span></div><div class="category-product-copy"><strong>${esc(w.name)}</strong><small>${esc(w.location.split(',')[0])} · ${w.stock.toLocaleString()} kg</small><div class="category-product-price"><b>${money(w.price)}</b><span>/ sack</span></div></div></button><button class="category-product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button><button class="category-product-add" data-add="${w.id}" aria-label="Add ${esc(w.name)} to order">${icon('shopping_bag')}</button></article>`}
function homeSearchResults(q){const term=q.trim().toLowerCase();if(!term)return '';const matches=db.inventory.filter(w=>(`${w.name} ${w.category} ${w.location}`).toLowerCase().includes(term));return `<div class="home-search-results" role="listbox" aria-label="Search results">${matches.length?matches.slice(0,5).map(w=>`<button type="button" class="home-search-result" data-home-result="${w.id}"><img src="${imageFor(w.color)}" alt=""><span><strong>${esc(w.name)}</strong><small>${esc(w.category)} · ${esc(w.location.split(',')[0])}</small></span><b>${money(w.price)}</b></button>`).join(''):`<div class="home-search-empty">${icon('search')}<span><strong>No matching supplies</strong><small>Try another waste type, category, or location.</small></span></div>`}</div>`}
let promoTimer=null,promoTouchX=0;
function farmerPromo(){const slides=db.inventory.slice(0,4);return `<article class="farmer-promo" aria-label="Featured organic waste">${slides.map((w,i)=>`<section class="farmer-promo-slide ${i===0?'active':''}" data-promo-slide="${i}" aria-hidden="${i!==0}"><div class="farmer-promo-copy"><span class="promo-kicker">FRESH FROM ${esc(w.location.split(',')[0]).toUpperCase()}</span><h2>${esc(w.name)}.<br>Ready for your farm.</h2><p>Quality-checked ${esc(w.category.toLowerCase())}, ready for your BSF farm.</p><button data-go="product/${w.id}">Explore product ${icon('arrow_forward')}</button></div><div class="farmer-promo-art" role="img" aria-label="${esc(w.name)}" style="--promo-image:url('${imageFor(w.color)}')"></div></section>`).join('')}<div class="farmer-promo-dots" aria-label="Featured supplies">${slides.map((w,i)=>`<button type="button" class="${i===0?'active':''}" data-promo-index="${i}" aria-label="Show ${esc(w.name)}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div></article>`}
function startPromoCarousel(){clearInterval(promoTimer);const root=document.querySelector('.farmer-promo');if(!root)return;const advance=step=>{const slides=[...root.querySelectorAll('[data-promo-slide]')],dots=[...root.querySelectorAll('[data-promo-index]')];if(!slides.length)return;let i=slides.findIndex(x=>x.classList.contains('active'));i=(i+step+slides.length)%slides.length;slides.forEach((x,n)=>{x.classList.toggle('active',n===i);x.setAttribute('aria-hidden',n===i?'false':'true')});dots.forEach((x,n)=>{x.classList.toggle('active',n===i);x.setAttribute('aria-current',n===i?'true':'false')})};root.addEventListener('touchstart',e=>{promoTouchX=e.changedTouches[0].clientX},{passive:true});root.addEventListener('touchend',e=>{let dx=e.changedTouches[0].clientX-promoTouchX;if(Math.abs(dx)>40)advance(dx<0?1:-1)},{passive:true});promoTimer=setInterval(()=>advance(1),4500)}
function home(){const recent=db.orders[0];return `<div class="page farmer-home-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div><div class="farmer-search-wrap"><label class="farmer-search">${icon('search')}<input id="home-search" type="search" autocomplete="off" placeholder="Search organic waste" value="${esc(search)}" aria-label="Search organic waste"></label><div id="home-search-results">${homeSearchResults(search)}</div></div></section><section class="farmer-mobile-content">${farmerPromo()}<section class="mobile-category-section"><div class="mobile-section-title"><h2>Categories</h2><button class="text-link" data-go="category">See all</button></div><div class="mobile-categories"><button class="${filter==='Fruit waste'?'selected':''}" data-set-filter="Fruit waste"><span class="category-pictogram category-fruit" aria-hidden="true"><img src="couple-of-half-oranges-svgrepo-com.svg" alt=""></span><small>Fruit waste</small></button><button class="${filter==='Vegetable scraps'?'selected':''}" data-set-filter="Vegetable scraps"><span class="category-pictogram category-vegetables" aria-hidden="true"><img src="cutlery-cross-couple-of-fork-and-spoon-svgrepo-com.svg" alt=""></span><small>Vegetables</small></button><button class="${filter==='Crop residues'?'selected':''}" data-set-filter="Crop residues"><span class="category-pictogram category-agriculture" aria-hidden="true"><img src="agriculture-svgrepo-com.svg" alt=""></span><small>Crop waste</small></button><button class="${filter==='All'?'selected':''}" data-set-filter="All"><span class="category-pictogram category-all-waste" aria-hidden="true"><img src="recycle-svgrepo-com.svg" alt=""></span><small>All waste</small></button></div></section><section class="mobile-best-section"><div class="mobile-section-title"><h2>${filter==='All'?'Best for your farm':filter==='Fruit waste'?'Fruit waste supplies':filter==='Vegetable scraps'?'Vegetable supplies':'Crop waste supplies'}</h2><button class="text-link" data-go="category">See all</button></div>${(()=>{const matches=db.inventory.filter(w=>filter==='All'||w.category===filter);return matches.length?`<div class="category-product-grid">${matches.map(categoryProductCard).join('')}</div>`:`<div class="home-filter-empty">No supplies in this category yet. Check back soon.</div>`})()}</section>${recent?`<section class="mobile-next-order"><div><span class="promo-kicker">YOUR LATEST ORDER</span><strong>${recent.id} · ${recent.status}</strong><small>${recent.items.map(x=>x.name).join(', ')}</small></div><button data-go="tracking">${icon('arrow_forward')}</button></section>`:''}</section><div class="home-desktop"><section class="hero"><div class="hero-content"><div class="eyebrow">${icon('wb_sunny')} ${greeting()}, ${esc(db.user.name.split(' ')[0])}</div><h1>Your farm is growing. Let’s keep it that way.</h1><p>Fresh, quality-checked organic feedstock is ready for your next BSF cycle.</p><div class="hero-actions"><button class="btn btn-accent" data-go="market">Browse the marketplace ${icon('arrow_forward')}</button><button class="btn btn-white" data-go="orders">View my orders</button></div></div><div class="hero-illustration">🌿</div></section><div class="grid stats-grid">${stat('Active orders',db.orders.filter(o=>!['Delivered','Cancelled'].includes(o.status)).length,'local_shipping','↑ Your supplies are on the way')}${stat('This month',db.orders.reduce((s,o)=>s+o.total,0)?money(db.orders.reduce((s,o)=>s+o.total,0)):'UGX 0','payments','Your farm investment')}${stat('Waste diverted','2.4 tonnes','compost','↑ 18% this season')}${stat('Farm impact','860 kg CO₂','eco','Saved from landfill')}</div><div class="grid dashboard-cols"><section><div class="section-head"><h2>Popular near your farm</h2><button class="text-link" data-go="market">View marketplace ${icon('arrow_forward')}</button></div><div class="grid waste-grid">${db.inventory.slice(0,3).map(wasteCard).join('')}</div></section><section class="card pad"><div class="section-head"><h2>Your latest order</h2><button class="text-link" data-go="orders">See all</button></div>${recent?orderMini(recent):`<div class="empty">${icon('inventory_2')}<p>No orders yet. Your next growing cycle starts here.</p><button class="btn btn-soft" data-go="market">Explore supplies</button></div>`}<div class="section-head" style="margin-top:24px"><h2>From our collection team</h2></div><div class="list">${db.collections.slice(0,2).map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(c.type)} collected</strong><small>${esc(c.place)} · ${esc(c.date)}</small></div><span class="badge ${c.status==='Awaiting review'?'orange':''}">${esc(c.status)}</span></div>`).join('')}</div></section></div></div></div>`}
function categoryPage(){const title=filter==='All'?'All organic waste':filter==='Fruit waste'?'Fruit waste':filter==='Vegetable scraps'?'Vegetable waste':'Crop waste';const items=db.inventory.filter(w=>filter==='All'||w.category===filter);return `<div class="page farmer-home-page category-page"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div><div class="farmer-search-wrap"><label class="farmer-search">${icon('search')}<input id="home-search" type="search" autocomplete="off" placeholder="Search organic waste" value="${esc(search)}" aria-label="Search organic waste"></label><div id="home-search-results">${homeSearchResults(search)}</div></div></section><section class="farmer-mobile-content category-mobile-content"><div class="category-page-heading"><button class="category-back" data-go="home">${icon('arrow_back')}</button><div><span class="promo-kicker">BROWSE SUPPLIES</span><h1>${title}</h1></div></div><section class="mobile-category-section category-page-filters"><div class="mobile-section-title"><h2>Categories</h2></div><div class="mobile-categories"><button class="${filter==='Fruit waste'?'selected':''}" data-set-filter="Fruit waste"><span class="category-pictogram category-fruit"><img src="couple-of-half-oranges-svgrepo-com.svg" alt=""></span><small>Fruit waste</small></button><button class="${filter==='Vegetable scraps'?'selected':''}" data-set-filter="Vegetable scraps"><span class="category-pictogram category-vegetables"><img src="cutlery-cross-couple-of-fork-and-spoon-svgrepo-com.svg" alt=""></span><small>Vegetables</small></button><button class="${filter==='Crop residues'?'selected':''}" data-set-filter="Crop residues"><span class="category-pictogram category-agriculture"><img src="agriculture-svgrepo-com.svg" alt=""></span><small>Crop waste</small></button><button class="${filter==='All'?'selected':''}" data-set-filter="All"><span class="category-pictogram category-all-waste"><img src="recycle-svgrepo-com.svg" alt=""></span><small>All waste</small></button></div></section><section class="category-matches"><div class="mobile-section-title"><h2>${title}</h2><span class="category-count">${items.length} supplies</span></div>${items.length?`<div class="category-product-grid">${items.map(categoryProductCard).join('')}</div>`:`<div class="category-empty"><strong>No supplies listed yet</strong><span>Our collection team is gathering this waste type. Check back soon.</span></div>`}</section></section></div>`}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}
function favoritesPage(){const items=db.inventory.filter(w=>db.favorites.includes(w.id));return `<div class="page farmer-home-page favorites-mobile"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div></section><section class="farmer-mobile-content favorites-content"><div class="explore-heading"><div><span class="promo-kicker">YOUR SAVED SUPPLIES</span><h1>Favorites</h1><p>Keep your go-to feedstock close at hand.</p></div></div>${items.length?`<div class="category-product-grid">${items.map(categoryProductCard).join('')}</div>`:`<div class="orders-empty favorites-empty"><div class="orders-empty-icon">${icon('favorite')}</div><h2>No favorites yet</h2><p>Save supplies with the heart button and they’ll be collected here.</p><button class="btn btn-primary" data-go="market">Explore supplies ${icon('arrow_forward')}</button></div>`}</section></div>`}
function orderHistoryPanel(){const orders=db.orders;const filtered=orders.filter(o=>orderFilter==='All'||(orderFilter==='Received'&&o.status==='Order received')||(orderFilter==='Pending'&&!['Order received','Delivered','Cancelled'].includes(o.status))||(orderFilter==='Cancelled'&&o.status==='Cancelled'));return `<section class="cart-order-history"><div class="section-head"><div><h2>Recent orders</h2><small>Track your orders and delivery status.</small></div><span class="badge">${orders.length} total</span></div><div class="order-filter-tabs">${['All','Received','Pending','Cancelled'].map(x=>`<button class="${orderFilter===x?'active':''}" data-order-filter="${x}">${x}<small>${x==='All'?orders.length:x==='Received'?orders.filter(o=>o.status==='Order received').length:x==='Pending'?orders.filter(o=>!['Order received','Delivered','Cancelled'].includes(o.status)).length:orders.filter(o=>o.status==='Cancelled').length}</small></button>`).join('')}</div>${filtered.length?`<div class="cart-order-list">${filtered.map(o=>`<article class="cart-order-row"><div class="cart-order-row-head"><div><strong>${esc(o.id)}</strong><small>${esc(o.date)}</small></div><span class="badge ${o.status==='Delivered'?'':'orange'}">${esc(o.status)}</span></div><div class="cart-order-row-items">${o.items.map(i=>`${i.qty} × ${esc(i.name)}`).join(' · ')}</div><div class="cart-order-row-foot"><span>${icon('location_on')} ${esc(o.address)}</span><strong>${money(o.total)}</strong></div></article>`).join('')}</div>`:`<div class="orders-empty cart-history-empty"><div class="orders-empty-icon">${icon('local_shipping')}</div><h2>${orderFilter==='All'?'No orders yet':`No ${orderFilter.toLowerCase()} orders`}</h2><p>Orders and delivery updates will appear here after checkout.</p><button class="btn btn-primary" data-go="market">Explore supplies ${icon('arrow_forward')}</button></div>`}</section>`}
function productDetail(id){
 const w=db.inventory.find(x=>x.id===id);
 if(!w)return `<div class="page"><button class="btn btn-outline" data-go="market">${icon('arrow_back')} Back to Explore</button><section class="card empty" style="margin-top:20px"><h2>Supply not found</h2><p>This listing may no longer be available.</p></section></div>`;
 const categoryText=w.category==='Fruit waste'?'Fruit processing and market trimmings selected for fresh BSF feedstock.':w.category==='Crop residues'?'Locally gathered crop by-products prepared as a practical feedstock for BSF farms.':'Fresh vegetable market trimmings sorted and checked before they are offered to farmers.';
 const related=db.inventory.filter(x=>x.id!==w.id&&x.category===w.category).slice(0,4);
 return `<div class="page farmer-home-page product-mobile"><section class="farmer-mobile-head product-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div></section><section class="product-mobile-content"><div class="product-mobile-photo" style="background-image:url('${imageFor(w.color)}')"><button class="product-back-icon" data-go="market" aria-label="Back to Explore">${icon('arrow_back')}</button><span class="product-quality-tag">${icon('verified')} Quality checked</span><button class="product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button></div><div class="product-mobile-info"><div class="product-mobile-category"><span>${esc(w.category)}</span><span class="product-stock-label"><i></i> Available now</span></div><h1>${esc(w.name)}</h1><div class="product-location">${icon('location_on')} ${esc(w.location)}</div><p class="product-description">${categoryText}</p><section class="product-source-card"><div class="product-source-icon">${icon(w.category==='Fruit waste'?'nutrition':w.category==='Crop residues'?'agriculture':'recycling')}</div><div><strong>Collected ${esc(w.fresh.replace(/^Collected /i,''))}</strong><small>Sorted by our local collection team</small></div><span class="product-source-check">${icon('verified')}</span></section><div class="product-detail-facts"><div><span>Available quantity</span><strong>${w.stock.toLocaleString()} kg</strong></div><div><span>Order unit</span><strong>${esc(w.unit)}</strong></div><div><span>Collection point</span><strong>${esc(w.location.split(',')[0])}</strong></div></div><div class="product-buy-row"><div class="product-detail-price"><strong>${money(w.price)}</strong><span>/ sack</span></div><div class="product-quantity-control"><button data-product-qty="dec" aria-label="Decrease quantity">−</button><input id="product-qty" type="number" min="1" value="1" aria-label="Quantity in sacks"><button data-product-qty="inc" aria-label="Increase quantity">+</button></div></div><button class="btn btn-primary btn-block product-add" data-add="${w.id}" data-add-qty="1">${icon('shopping_bag')} Add to order</button><div class="product-delivery-note">Delivery to Wakiso is arranged after our team confirms your order.</div>${related.length?`<section class="product-related"><div class="mobile-section-title"><h2>More ${esc(w.category.toLowerCase())}</h2><button class="text-link" data-go="market">See all</button></div><div class="mobile-waste-rail">${related.map(mobileWasteCard).join('')}</div></section>`:''}</div></section></div><div class="page product-detail-page product-desktop"><button class="btn btn-outline product-back" data-go="market">${icon('arrow_back')} Back to Explore</button><div class="product-detail-grid"><div class="product-detail-photo" style="background-image:url('${imageFor(w.color)}')"><span class="tag">${icon('verified')} Quality checked</span><button class="product-favorite ${db.favorites.includes(w.id)?'saved':''}" data-favorite="${w.id}" aria-label="Toggle favorite">${icon('favorite')}</button></div><section class="product-detail-info"><div class="eyebrow">${esc(w.category)}</div><h1>${esc(w.name)}</h1><div class="product-location">${icon('location_on')} ${esc(w.location)}</div><p class="product-description">${categoryText} Each sack is listed at ${money(w.price)} and sourced through Green Divert for Africa’s collection network.</p><div class="product-detail-facts"><div><span>Available stock</span><strong>${w.stock.toLocaleString()} kg</strong></div><div><span>Collection status</span><strong>${esc(w.fresh)}</strong></div><div><span>Order unit</span><strong>${esc(w.unit)}</strong></div></div><div class="product-detail-price"><strong>${money(w.price)}</strong><span>/ ${esc(w.unit)}</span></div><button class="btn btn-primary btn-block product-add" data-add="${w.id}">${icon('shopping_bag')} Add to order</button><small class="product-delivery-note">Delivery to Wakiso is arranged after the team confirms your order.</small></section></div></div>`
}
function marketplace(){let items=db.inventory.filter(w=>(filter==='All'||w.category===filter)&&(`${w.name} ${w.category} ${w.location}`).toLowerCase().includes(search.toLowerCase()));let empty=`<div class="category-empty"><strong>No matching supplies</strong><span>Try a different search or category.</span></div>`;return `<div class="page farmer-home-page explore-mobile"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div><label class="farmer-search">${icon('search')}<input id="market-search-mobile" type="search" autocomplete="off" value="${esc(search)}" placeholder="Search organic waste" aria-label="Search organic waste"></label></section><section class="farmer-mobile-content explore-mobile-content"><div class="explore-heading"><div><span class="promo-kicker">FRESHLY COLLECTED</span><h1>Explore supplies</h1><p>Quality-checked organic waste, ready for your farm.</p></div><button class="explore-cart-button" data-go="cart" aria-label="Open your order">${icon('shopping_bag')}<i>${db.cart.reduce((a,x)=>a+x.qty,0)}</i></button></div><section class="mobile-category-section explore-categories"><div class="mobile-section-title"><h2>Categories</h2></div><div class="mobile-categories"><button class="${filter==='Fruit waste'?'selected':''}" data-filter="Fruit waste"><span class="category-pictogram category-fruit"><img src="couple-of-half-oranges-svgrepo-com.svg" alt=""></span><small>Fruit waste</small></button><button class="${filter==='Vegetable scraps'?'selected':''}" data-filter="Vegetable scraps"><span class="category-pictogram category-vegetables"><img src="cutlery-cross-couple-of-fork-and-spoon-svgrepo-com.svg" alt=""></span><small>Vegetables</small></button><button class="${filter==='Crop residues'?'selected':''}" data-filter="Crop residues"><span class="category-pictogram category-agriculture"><img src="agriculture-svgrepo-com.svg" alt=""></span><small>Crop waste</small></button><button class="${filter==='All'?'selected':''}" data-filter="All"><span class="category-pictogram category-all-waste"><img src="recycle-svgrepo-com.svg" alt=""></span><small>All waste</small></button></div></section><section class="explore-products"><div class="mobile-section-title"><div><h2>${filter==='All'?'Available supplies':filter==='Fruit waste'?'Fruit waste':filter==='Vegetable scraps'?'Vegetables':'Crop waste'}</h2><small>${items.length} fresh supplies · prices per sack</small></div><select class="explore-sort" id="sort-select-mobile"><option value="recommended">Recommended</option><option value="price">Lowest price</option><option value="stock">Most stock</option></select></div><div class="category-product-grid" id="market-grid-mobile">${items.length?items.map(categoryProductCard).join(''):empty}</div></section></section></div><div class="page explore-desktop"><div class="page-heading"><div><div class="eyebrow">The marketplace</div><h1>Good inputs. Better harvests.</h1><p>Fresh organic feedstock, collected and quality checked for your farm.</p></div><button class="btn btn-primary" data-go="cart">${icon('shopping_bag')} Your order <span class="badge" style="background:#ffffff32;color:#fff">${db.cart.reduce((a,x)=>a+x.qty,0)}</span></button></div><div class="toolbar"><label class="searchbar">${icon('search')}<input id="market-search" value="${esc(search)}" placeholder="Search waste, category or location"></label><div class="toolbar-group"><button class="btn btn-outline" data-action="filters">${icon('tune')} Filters</button><select class="select" id="sort-select"><option value="recommended">Recommended</option><option value="price">Price: low to high</option><option value="stock">Most available</option></select></div></div><div class="chips">${['All','Vegetable scraps','Fruit waste','Crop residues'].map(x=>`<button class="chip ${filter===x?'active':''}" data-filter="${x}">${x==='All'?'All supplies':x}</button>`).join('')}</div><div class="section-head"><div><h2>${items.length} fresh supplies</h2><span class="muted tiny">Prices per 50 kg sack · UGX</span></div><span class="badge">${icon('verified')} Quality checked</span></div><div class="grid waste-grid" id="market-grid">${items.length?items.map(wasteCard).join(''):`<div class="empty card" style="grid-column:1/-1">No supplies match that search.</div>`}</div><div class="notice green" style="margin-top:22px">${icon('local_shipping')} <span><strong>Delivery to Wakiso:</strong> Most orders arrive within 1–2 working days. Delivery fee is calculated at checkout.</span></div></div>`}
function cartPage(){let lines=db.cart.map(c=>{let w=db.inventory.find(x=>x.id===c.id);return w?{...w,qty:c.qty}:null}).filter(Boolean);let subtotal=lines.reduce((s,w)=>s+w.price*w.qty,0),delivery=lines.length?15000:0;return `<div class="order-page-shell"><section class="farmer-mobile-head order-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div></section><div class="page order-page"><div class="page-heading"><div><div class="eyebrow">Your order</div><h1>Review your supplies</h1><p>Check quantities before you send your order to our team.</p></div></div>${lines.length?`<div class="two-col"><section class="card pad"><div class="section-head"><h2>Order items <span class="muted">(${lines.length})</span></h2><button class="text-link" data-action="clear-cart">Clear all</button></div>${lines.map(w=>`<div class="cart-item"><div class="table-emoji" style="width:52px;height:52px;font-size:25px">${w.emoji}</div><div class="row-main"><strong>${esc(w.name)}</strong><small>${money(w.price)} / ${esc(w.unit)} · ${esc(w.location)}</small></div><div class="qty"><button data-qty="${w.id}" data-delta="-1">−</button><span>${w.qty}</span><button data-qty="${w.id}" data-delta="1">+</button></div><strong>${money(w.price*w.qty)}</strong><button class="icon-btn" data-remove="${w.id}">${icon('close')}</button></div>`).join('')}<div class="field" style="margin-top:22px"><label>Delivery address</label><select><option>David’s BSF Farm · Wakiso, Central Region</option><option>Add a new delivery address…</option></select></div><div class="field" style="margin-top:15px"><label>Delivery notes (optional)</label><textarea placeholder="Landmark, gate instructions, or a good time to call"></textarea></div></section><aside class="card pad"><h2>Order summary</h2><p class="muted tiny">A team member will confirm your delivery window.</p><div class="summary-line"><span>Supplies (${lines.reduce((a,w)=>a+w.qty,0)} sacks)</span><strong>${money(subtotal)}</strong></div><div class="summary-line"><span>Delivery to Wakiso</span><strong>${money(delivery)}</strong></div><div class="summary-line"><span>Estimated taxes</span><strong>Included</strong></div><div class="summary-line total"><span>Total</span><span>${money(subtotal+delivery)}</span></div><div class="notice" style="margin:15px 0">${icon('payments')} <span>Pay securely with <strong>MTN Mobile Money</strong> after our team confirms your order.</span></div><button class="btn btn-primary btn-block order-submit-button" data-action="place-order">Place my order ${icon('arrow_forward')}</button><p class="muted tiny" style="text-align:center;margin:13px 0 0">No payment is taken until the order is confirmed.</p></aside></div>`:`<section class="card empty">${icon('shopping_bag')}<h2>Your order is waiting to be filled</h2><p>Browse locally collected organic supplies and add what your farm needs.</p><button class="btn btn-primary shop-now-button" data-go="market">${icon('shopping_cart')} Shop now</button></section>`}</div></div>`}
function placeOrder(){if(!db.cart.length)return;const total=db.cart.reduce((s,c)=>{let w=db.inventory.find(x=>x.id===c.id);return s+(w?w.price*c.qty:0)},0)+15000;const order={id:'GD-'+String(Date.now()).slice(-6),date:new Date().toLocaleDateString('en-UG',{day:'numeric',month:'short',year:'numeric'}),items:db.cart.map(c=>{let w=db.inventory.find(x=>x.id===c.id);return {name:w.name,qty:c.qty,emoji:w.emoji,price:w.price}}),total,status:'Order received',address:'David’s BSF Farm · Wakiso',progress:0};db.orders.unshift(order);db.cart=[];save();go('confirmation')}
function confirmation(){let o=db.orders[0];return `<div class="page"><section class="card pad" style="max-width:760px;margin:35px auto;text-align:center;padding:45px 32px"><div style="width:76px;height:76px;border-radius:50%;margin:0 auto 20px;background:#e9f5eb;color:var(--green);display:grid;place-items:center;font-size:36px">${icon('check_circle')}</div><div class="eyebrow">Order placed</div><h1 style="margin-top:9px">Your farm’s next delivery is in motion.</h1><p class="muted" style="max-width:500px;margin:10px auto 22px">We’ve sent your order to the Green Divert team. We’ll call to confirm availability and your delivery window.</p><div class="order-banner" style="max-width:490px;margin:0 auto 24px;text-align:left"><span><small class="muted">ORDER REFERENCE</small><br><strong>${o?.id}</strong></span><span class="badge orange">${o?.status}</span></div><div style="display:flex;gap:10px;justify-content:center;flex-wrap:wrap"><button class="btn btn-primary" data-go="tracking">Track this order ${icon('arrow_forward')}</button><button class="btn btn-outline" data-go="market">Continue shopping</button></div></section></div>`}
function orderMini(o){return `<div class="order-banner"><span><small class="muted">${o.id} · ${o.date}</small><br><strong>${money(o.total)}</strong></span><span class="badge orange">${o.status}</span></div><div class="list">${o.items.map(x=>`<div class="list-row"><div class="table-emoji">${x.emoji}</div><div class="row-main"><strong>${esc(x.name)}</strong><small>${x.qty} × 50 kg sacks</small></div><strong>${money(x.price*x.qty)}</strong></div>`).join('')}</div><button class="btn btn-soft btn-block" style="margin-top:15px" data-go="tracking">View order progress ${icon('arrow_forward')}</button>`}
function tracking(){
 const orders=db.orders;
 const inFilter=o=>orderFilter==='All'||(orderFilter==='Received'&&o.status==='Order received')||(orderFilter==='Pending'&&!['Order received','Delivered','Cancelled'].includes(o.status))||(orderFilter==='Cancelled'&&o.status==='Cancelled');
 const countFor=x=>x==='All'?orders.length:x==='Received'?orders.filter(o=>o.status==='Order received').length:x==='Pending'?orders.filter(o=>!['Order received','Delivered','Cancelled'].includes(o.status)).length:orders.filter(o=>o.status==='Cancelled').length;
 const visible=orders.filter(inFilter);
 const mobileOrders=visible.map(o=>{
  const progress=Math.max(0,o.progress||0),steps=['Received','Confirmed','Preparing','On the way','Delivered'],current=steps[Math.min(progress,4)];
  return `<article class="mobile-order-card"><div class="mobile-order-top"><div><span class="promo-kicker">${esc(o.id)}</span><small>Placed ${esc(o.date)}</small></div><span class="badge ${progress>=3?'':'orange'}">${esc(o.status)}</span></div><h2>${o.items.map(i=>esc(i.name)).join(', ')}</h2><div class="mobile-order-meta"><span>${(()=>{const qty=o.items.reduce((a,i)=>a+i.qty,0);return `${qty} sack${qty===1?'':'s'}`})()}</span><i></i><strong>${money(o.total)}</strong></div><div class="order-progress-track">${steps.map((step,i)=>`<span class="${i<=progress?'done':''} ${i===progress?'current':''}"></span>`).join('')}</div><div class="order-stage-labels">${steps.map((step,i)=>`<span class="${i===progress?'current':''}">${step==='Confirmed'?'Confirm':step==='Preparing'?'Prepare':step==='On the way'?'On way':step}</span>`).join('')}</div><div class="order-current-step">${icon(progress>=4?'check_circle':'local_shipping')}<span><small>Current status</small><strong>${esc(current)}</strong></span></div><div class="mobile-order-next">${icon('schedule')}<span><small>Next update</small><strong>${progress>=4?'Delivered to your farm.':progress===3?'Your delivery is on the way to your farm.':progress===2?'Your order is being prepared for dispatch.':progress===1?'Our team is arranging your delivery window.':o.status==='Cancelled'?'This order was cancelled. Contact us if you need help.':'Our team will confirm availability and delivery timing.'}</strong></span></div><div class="mobile-order-delivery">${icon('location_on')}<span>${esc(o.address)}</span></div><button class="mobile-order-contact" data-action="help">${icon('call')} Contact Green Divert</button></article>`
 }).join('');
 const filters=['All','Received','Pending','Cancelled'];
 const desktopOrders=orders.length?orders.map(o=>`<div class="card pad desktop-order-card" style="margin-bottom:17px"><div class="section-head"><div><div class="eyebrow">${esc(o.id)}</div><h2 style="margin:5px 0 0">${o.items.map(i=>esc(i.name)).join(', ')}</h2><span class="muted tiny">Placed ${esc(o.date)} · ${o.items.reduce((sum,i)=>sum+i.qty,0)} sacks · ${money(o.total)}</span></div><span class="badge ${(o.progress||0)>=3?'':'orange'}">${esc(o.status)}</span></div><div class="trackline">${['Received','Confirmed','Preparing','On the way','Delivered'].map((step,i)=>`<div class="track-step ${i<=(o.progress||0)?'done':''}"><span class="track-dot">${i<(o.progress||0)?icon('check'):i+1}</span><span>${step}</span></div>`).join('')}</div><div class="list-row"><div class="list-icon">${icon('location_on')}</div><div class="row-main"><strong>Delivery address</strong><small>${esc(o.address)}</small></div><button class="btn btn-outline" data-action="help">${icon('call')} Contact team</button></div></div>`).join(''):`<div class="card empty">${icon('local_shipping')}<h2>No deliveries to track yet</h2><p>Your orders will appear here as soon as you place one.</p><button class="btn btn-primary" data-go="market">Browse supplies</button></div>`;
 return `<div class="page farmer-home-page orders-mobile"><section class="farmer-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div></section><section class="farmer-mobile-content orders-mobile-content"><div class="orders-title-row"><div><span class="promo-kicker">YOUR FARM SUPPLIES</span><h1>My orders</h1><p>Track your supplies from collection to delivery.</p></div><button class="orders-shop" data-go="market">${icon('add')}<span>Shop</span></button></div><div class="order-filter-tabs">${filters.map(x=>`<button class="${orderFilter===x?'active':''}" data-order-filter="${x}">${x}<small>${countFor(x)}</small></button>`).join('')}</div>${mobileOrders||`<div class="orders-empty"><div class="orders-empty-icon">${icon('local_shipping')}</div><h2>${orderFilter==='All'?'No orders yet':`No ${orderFilter.toLowerCase()} orders`}</h2><p>${orderFilter==='All'?'Your supplies and delivery updates will appear here after you place an order.':'Try another order filter, or browse available organic waste.'}</p><button class="btn btn-primary" data-go="market">Explore supplies ${icon('arrow_forward')}</button></div>`}</section></div><div class="orders-desktop"><div class="page"><div class="page-heading"><div><div class="eyebrow">Stay in the loop</div><h1>Orders & delivery</h1><p>Follow every order from confirmation to your farm gate.</p></div><button class="btn btn-primary" data-go="market">${icon('add')} Place an order</button></div>${desktopOrders}</div></div>`
}
function profile(){return `<div class="page farmer-home-page profile-mobile"><section class="farmer-mobile-head profile-mobile-head"><div class="farmer-greeting-row"><div class="avatar farmer-head-avatar">${userAvatar()}</div><div class="farmer-greeting-copy"><span>Hi, ${esc(db.user.name.split(' ')[0])}</span><strong>${icon('location_on')} Wakiso, Central Region</strong></div><button class="farmer-notifications" data-action="notifications" aria-label="Notifications">${icon('notifications')}<i></i></button></div></section><section class="farmer-mobile-content profile-mobile-content"><div class="profile-title-block"><span class="promo-kicker">YOUR FARM ACCOUNT</span><h1>My profile</h1><p>Keep your details up to date for smooth deliveries.</p></div><section class="profile-identity-card"><div class="profile-identity-avatar">${userAvatar()}</div><div class="profile-identity-copy"><strong>${esc(db.user.name)}</strong><span>BSF Farmer · Member since 2024</span></div><button data-action="avatar" aria-label="Change avatar">${icon('edit')}</button><span class="profile-verified">${icon('verified')} Verified</span></section><section class="profile-mobile-card"><div class="profile-card-heading"><span class="profile-section-icon">${icon('person')}</span><div><h2>Personal details</h2><small>Your contact information</small></div></div><label class="profile-field">Full name<input id="profile-name" value="${esc(db.user.name)}"></label><label class="profile-field">Phone number<input value="+256 772 456 890" inputmode="tel"></label><label class="profile-field">Email address<input value="christine@example.com" type="email"></label></section><section class="profile-mobile-card"><div class="profile-card-heading"><span class="profile-section-icon">${icon('agriculture')}</span><div><h2>Farm details</h2><small>Delivery and farm information</small></div></div><label class="profile-field">Farm / business name<input value="Christine BSF Farm"></label><label class="profile-field">Farm type<select><option>Black Soldier Fly (BSF)</option><option>Mixed livestock</option><option>Crop farming</option></select></label><label class="profile-field">Farm location<input value="Wakiso District, Central Region"></label><div class="profile-service-note">${icon('verified_user')} <span><strong>Delivery area verified</strong><small>Wakiso is within our service zone.</small></span></div></section><button class="btn btn-primary btn-block profile-save-button" data-action="save-profile">${icon('save')} Save changes</button><button class="profile-help-link" data-action="help">${icon('support_agent')} Need help with your account? <span>${icon('arrow_forward')}</span></button><button class="profile-logout" data-action="logout">${icon('logout')} Sign out</button></section></div><div class="profile-desktop"><div class="page"><div class="page-heading"><div><div class="eyebrow">Your account</div><h1>My farm profile</h1><p>Keep your farm details up to date so deliveries reach you smoothly.</p></div><button class="btn btn-primary" data-action="save-profile">${icon('save')} Save changes</button></div><div class="two-col"><section class="card pad"><div style="display:flex;align-items:center;gap:14px;margin-bottom:23px"><div class="avatar" style="width:60px;height:60px;font-size:30px">${userAvatar()}</div><div><h3 style="margin:0">${esc(db.user.name)}</h3><span class="muted tiny">BSF Farmer · Member since 2024</span></div><button class="btn btn-soft" style="margin-left:auto" data-action="avatar">Change avatar</button></div><div class="form-grid"><label class="field">Full name<input value="${esc(db.user.name)}"></label><label class="field">Phone number<input value="+256 772 456 890"></label><label class="field">Email address<input value="christine@example.com"></label><label class="field">Farm type<select><option>Black Soldier Fly (BSF)</option><option>Mixed livestock</option><option>Crop farming</option></select></label><label class="field full">Farm / business name<input value="Christine BSF Farm"></label><label class="field full">Farm location<input value="Wakiso District, Central Region"></label></div></section><aside class="card pad"><h2>Farm details</h2><div class="list"><div class="list-row"><div class="list-icon">${icon('location_on')}</div><div class="row-main"><strong>Delivery area</strong><small>Wakiso · within our service zone</small></div></div><div class="list-row"><div class="list-icon">${icon('eco')}</div><div class="row-main"><strong>Farming since</strong><small>2024 · 2 growing seasons</small></div></div><div class="list-row"><div class="list-icon">${icon('verified_user')}</div><div class="row-main"><strong>Account status</strong><small>Verified farmer</small></div><span class="badge">Active</span></div></div><button class="btn btn-outline btn-block" style="margin-top:18px" data-action="help">${icon('support_agent')} Get help with my account</button></aside></div></div></div>`}
function staffHome(){const low=db.inventory.filter(w=>w.stock<250).length;return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Operations overview</div><h1>Good morning, Amina 👋</h1><p>Here’s what’s moving across the Green Divert network today.</p></div><button class="btn btn-primary" data-go="collection">${icon('add')} Log a collection</button></div><div class="grid stats-grid">${stat('Available stock',db.inventory.reduce((s,w)=>s+w.stock,0).toLocaleString()+' kg','inventory_2','Across 6 waste categories')}${stat('Open orders',db.orders.filter(o=>o.progress<4).length+18,'receipt_long','↑ 6 new this week')}${stat('Collections today','860 kg','recycling','Across 4 collection points')}${stat('Needs attention',low+' low stock','warning','Review stock levels')}</div><div class="grid dashboard-cols"><section class="card pad"><div class="section-head"><h2>Latest farmer orders</h2><button class="text-link" data-go="stafforders">Manage orders ${icon('arrow_forward')}</button></div>${db.orders.length?`<div class="list">${db.orders.slice(0,4).map(o=>`<div class="list-row"><div class="list-icon">${icon('receipt_long')}</div><div class="row-main"><strong>${o.id} · ${o.items.map(i=>i.name).join(', ')}</strong><small>${o.address} · ${o.date}</small></div><strong>${money(o.total)}</strong><span class="badge orange">${o.status}</span><button class="icon-btn" data-order-status="${o.id}">${icon('more_horiz')}</button></div>`).join('')}</div>`:`<div class="list"><div class="list-row"><div class="list-icon">${icon('receipt_long')}</div><div class="row-main"><strong>GD-48291 · Banana peels, vegetable mix</strong><small>David Kato · Wakiso · Today, 10:24 AM</small></div><strong>UGX 350,000</strong><span class="badge orange">Needs confirmation</span><button class="icon-btn" data-action="sample-order">${icon('more_horiz')}</button></div><div class="list-row"><div class="list-icon">${icon('receipt_long')}</div><div class="row-main"><strong>GD-48290 · Maize bran</strong><small>Sarah Namusoke · Mukono · Today, 9:42 AM</small></div><strong>UGX 460,000</strong><span class="badge blue">Preparing</span><button class="icon-btn" data-action="sample-order">${icon('more_horiz')}</button></div><div class="list-row"><div class="list-icon">${icon('receipt_long')}</div><div class="row-main"><strong>GD-48287 · Pineapple waste</strong><small>J. Okello · Luwero · Yesterday</small></div><strong>UGX 215,000</strong><span class="badge">On the way</span></div></div>`}</section><section class="card pad"><div class="section-head"><h2>Recent collections</h2><button class="text-link" data-go="collection">View all</button></div><div class="list">${db.collections.slice(0,4).map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(c.type)} · ${c.qty} kg</strong><small>${esc(c.agent)} · ${esc(c.place)}</small></div><span class="badge ${c.status==='Awaiting review'?'orange':''}">${esc(c.status)}</span></div>`).join('')}</div><div class="section-head" style="margin-top:22px"><h2>Stock watch</h2><button class="text-link" data-go="inventory">Inventory</button></div>${db.inventory.filter(w=>w.stock<500).slice(0,3).map(w=>`<div class="list-row"><div class="table-emoji">${w.emoji}</div><div class="row-main"><strong>${w.name}</strong><small>${w.stock} kg remaining</small></div><span class="badge ${w.stock<250?'orange':''}">${w.stock<250?'Low stock':'Monitor'}</span></div>`).join('')}</section></div></div>`}
function inventoryPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Supply management</div><h1>Inventory & listings</h1><p>Keep marketplace availability accurate for every farmer.</p></div><button class="btn btn-primary" data-action="new-listing">${icon('add')} Add a listing</button></div><div class="toolbar"><label class="searchbar">${icon('search')}<input id="inventory-search" placeholder="Search inventory"></label><div class="toolbar-group"><select class="select" id="stock-filter"><option>All stock levels</option><option>Low stock</option><option>In stock</option></select><button class="btn btn-outline" data-action="export">${icon('download')} Export</button></div></div><section class="card table-wrap"><table class="table"><thead><tr><th>Supply listing</th><th>Category</th><th>Price / sack</th><th>Available</th><th>Source / area</th><th>Status</th><th></th></tr></thead><tbody id="inventory-body">${inventoryRows(db.inventory)}</tbody></table></section><div class="grid stats-grid" style="margin-top:18px">${stat('Total supply types',db.inventory.length,'category','Active marketplace listings')}${stat('Total available',db.inventory.reduce((s,w)=>s+w.stock,0).toLocaleString()+' kg','scale','Ready for allocation')}${stat('Low stock items',db.inventory.filter(w=>w.stock<250).length,'warning','Below 250 kg threshold')}${stat('Collections logged',db.collections.length,'recycling','This prototype session')}</div></div>`}
function inventoryRows(items){return items.map(w=>`<tr><td><div class="table-item"><span class="table-emoji">${w.emoji}</span>${esc(w.name)}</div></td><td>${esc(w.category)}</td><td>${money(w.price)}</td><td><strong>${w.stock.toLocaleString()} kg</strong></td><td>${esc(w.location)}</td><td><span class="badge ${w.stock<250?'orange':''}">${w.stock<250?'Low stock':'Available'}</span></td><td><button class="icon-btn" data-edit="${w.id}">${icon('edit')}</button></td></tr>`).join('')}
function collectionPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Field operations</div><h1>Log a collection</h1><p>Record incoming organic waste and update available inventory.</p></div><span class="badge">${icon('wifi')} Sync ready</span></div><div class="two-col"><section class="card pad"><div class="section-head"><h2>Collection details</h2><span class="badge">New field log</span></div><form id="collection-form"><div class="form-grid"><label class="field">Waste type<select name="type" required>${db.inventory.map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></label><label class="field">Collected quantity (kg)<input type="number" name="qty" min="1" placeholder="e.g. 250" required></label><label class="field">Field agent<select name="agent"><option>Sarah Namusoke</option><option>Peter Okello</option><option>Grace Akello</option><option>Myself</option></select></label><label class="field">Collection point<input name="place" placeholder="Market, farm, or collection hub" required></label><label class="field">Collection date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}"></label><label class="field">Quality check<select name="quality"><option>Passed — ready for inventory</option><option>Needs review</option><option>Rejected</option></select></label><label class="field full">Field notes<textarea name="notes" placeholder="Condition, moisture, contamination or other observations"></textarea></label><div class="field full"><button class="btn btn-primary btn-block">${icon('save')} Save collection & update stock</button></div></div></form></section><section><div class="card pad"><div class="section-head"><h2>Today’s field activity</h2><span class="badge">${db.collections.length} logs</span></div><div class="list">${db.collections.map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${esc(c.type)} · ${c.qty} kg</strong><small>${esc(c.agent)} · ${esc(c.place)}<br>${esc(c.date)}</small></div><span class="badge ${c.status==='Awaiting review'?'orange':''}">${esc(c.status)}</span></div>`).join('')}</div></div><div class="notice green" style="margin-top:15px">${icon('offline_bolt')} <span>Field logs are saved on this device for your demo. A connected deployment can sync them across the team.</span></div></section></div></div>`}
function staffOrders(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">Farmer demand</div><h1>Orders management</h1><p>Review incoming requests and keep farmers updated.</p></div><span class="badge">${db.orders.length+18} total orders</span></div><div class="toolbar"><label class="searchbar">${icon('search')}<input placeholder="Search order or farmer"></label><div class="toolbar-group"><select class="select"><option>All statuses</option><option>Order received</option><option>Confirmed</option><option>On the way</option></select></div></div><section class="card table-wrap"><table class="table"><thead><tr><th>Order</th><th>Farmer</th><th>Supplies</th><th>Order total</th><th>Date</th><th>Status</th><th>Update</th></tr></thead><tbody>${db.orders.length?db.orders.map(o=>`<tr><td><strong>${o.id}</strong></td><td>David Kato<br><small class="muted">Wakiso</small></td><td>${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join('<br>')}</td><td><strong>${money(o.total)}</strong></td><td>${o.date}</td><td><span class="badge orange">${o.status}</span></td><td><select class="select" data-status="${o.id}">${['Order received','Confirmed','Preparing','On the way','Delivered','Cancelled'].map(s=>`<option ${o.status===s?'selected':''}>${s}</option>`).join('')}</select></td></tr>`).join(''):`<tr><td><strong>GD-48291</strong></td><td>David Kato<br><small class="muted">Wakiso</small></td><td>4× Banana peels<br>2× Vegetable mix</td><td><strong>UGX 350,000</strong></td><td>Today, 10:24 AM</td><td><span class="badge orange">Needs confirmation</span></td><td><button class="btn btn-soft" data-action="sample-order">Review</button></td></tr><tr><td><strong>GD-48290</strong></td><td>Sarah Namusoke<br><small class="muted">Mukono</small></td><td>6× Maize bran</td><td><strong>UGX 460,000</strong></td><td>Today, 9:42 AM</td><td><span class="badge blue">Preparing</span></td><td><button class="btn btn-soft" data-action="sample-order">Review</button></td></tr>`}</tbody></table></section><div class="notice" style="margin-top:17px">${icon('info')} <span>Orders created in the farmer demo appear here instantly on this device.</span></div></div>`}
function agentsPage(){return `<div class="page"><div class="page-heading"><div><div class="eyebrow">People in the field</div><h1>Field agents</h1><p>Your collection network keeps quality supplies moving.</p></div><button class="btn btn-primary" data-action="invite-agent">${icon('person_add')} Add field agent</button></div><div class="grid waste-grid">${[['👩🏽‍🌾','Sarah Namusoke','Kampala Central','Active','14 collections','92% quality pass'],['👨🏿‍🌾','Peter Okello','Mukono & Jinja','On collection','9 collections','96% quality pass'],['👩🏾‍🌾','Grace Akello','Luwero District','Active','11 collections','95% quality pass']].map(a=>`<article class="card pad"><div style="display:flex;align-items:center;gap:12px"><div class="avatar" style="width:54px;height:54px;font-size:29px">${a[0]}</div><div style="flex:1"><h3 style="margin:0">${a[1]}</h3><span class="muted tiny">${icon('location_on')} ${a[2]}</span></div><span class="badge ${a[3]==='Active'?'':'orange'}">${a[3]}</span></div><div class="grid" style="grid-template-columns:1fr 1fr;margin:20px 0"><div><strong>${a[4]}</strong><div class="muted tiny">This month</div></div><div><strong>${a[5]}</strong><div class="muted tiny">Quality rating</div></div></div><div style="display:flex;gap:8px"><button class="btn btn-soft" style="flex:1" data-action="call-agent">${icon('call')} Call agent</button><button class="btn btn-outline" data-action="agent-history">${icon('history')} History</button></div></article>`).join('')}</div><section class="card pad" style="margin-top:20px"><div class="section-head"><h2>Collection coverage</h2><span class="badge">3 regions active</span></div><div class="map-card" style="height:280px"><div class="map-road"></div><div class="map-pin" style="left:33%;top:35%">${icon('recycling')}</div><div class="map-pin" style="left:56%;top:54%;background:var(--green)">${icon('recycling')}</div><div class="map-pin" style="left:72%;top:32%;background:#3978a4">${icon('recycling')}</div><span class="map-caption">Kampala · Mukono · Luwero</span></div></section></div>`}
function render(){if(!db.role){loginPage();return}let r=route();if(r.startsWith('product/')){shell(productDetail(r.slice(8)));return}let page=({category:categoryPage,home,market:marketplace,cart:cartPage,confirmation,orders:favoritesPage,favorites:favoritesPage,tracking,profile,staff:staffHome,inventory:inventoryPage,collection:collectionPage,stafforders:staffOrders,agents:agentsPage})[r]||home;let markup=page();if(r==='cart')markup=markup.replace(/<\/div>$/,`${orderHistoryPanel()}</div>`);shell(markup)}
function openModal(title,body,submitLabel='Save'){const m=document.createElement('div');m.className='modal-backdrop';m.innerHTML=`<div class="modal"><div class="modal-head"><h2>${title}</h2><button class="close" data-modal-close>${icon('close')}</button></div>${body}</div>`;document.body.appendChild(m);m.addEventListener('click',e=>{if(e.target===m||e.target.closest('[data-modal-close]'))m.remove();const f=e.target.closest('[data-filter]');if(f){filter=f.dataset.filter;m.remove();render()}if(e.target.closest('[data-action="reset-sent"]')){m.remove();toast('Demo reset code sent!')}if(e.target.closest('[data-action="invite-sent"]')){m.remove();toast('Agent invitation created')}if(e.target.closest('[data-action="sample-confirm"]')){m.remove();toast('Sample order confirmed')}});return m}
function listingModal(id){let w=db.inventory.find(x=>x.id===id)||{name:'',category:'Vegetable scraps',price:'',stock:'',location:'',emoji:'🥬',color:'vegetable',unit:'50 kg sack'};let m=openModal(id?'Edit marketplace listing':'Add a marketplace listing',`<form id="listing-form"><div class="form-grid"><label class="field full">Listing name<input name="name" value="${esc(w.name)}" required placeholder="e.g. Fresh market vegetable mix"></label><label class="field">Category<select name="category">${['Vegetable scraps','Fruit waste','Crop residues'].map(x=>`<option ${w.category===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="field">Price per sack (UGX)<input type="number" name="price" value="${w.price}" required></label><label class="field">Available quantity (kg)<input type="number" name="stock" value="${w.stock}" required></label><label class="field">Collection location<input name="location" value="${esc(w.location)}" required></label><label class="field">Emoji / image cue<input name="emoji" value="${w.emoji}"></label><label class="field">Availability<select name="fresh"><option>Collected today</option><option>Collected yesterday</option><option>Collected 2 days ago</option></select></label><div class="field full"><button class="btn btn-primary btn-block">${icon('save')} Save listing</button></div></div></form>`);m.querySelector('#listing-form').onsubmit=e=>{e.preventDefault();let f=new FormData(e.target),data={id:id||'w'+Date.now(),name:f.get('name'),category:f.get('category'),price:+f.get('price'),stock:+f.get('stock'),location:f.get('location'),emoji:f.get('emoji')||'♻️',fresh:f.get('fresh'),color:w.color||'vegetable',unit:'50 kg sack'};if(id)Object.assign(w,data);else db.inventory.unshift(data);save();m.remove();render();toast('Marketplace listing saved')};}
function signupModal(){let m=openModal('Create your farmer account',`<p class="muted">Join farmers building a more circular food system.</p><form id="signup-form"><div class="signup-photo-row"><div class="signup-photo-preview" id="signup-photo-preview">👩🏽‍🌾</div><label class="signup-photo-picker">Choose profile photo<input id="signup-photo-file" name="photo" type="file" accept="image/*"><small>JPG or PNG · optional</small></label></div><div class="form-grid"><label class="field">Full name<input name="name" placeholder="Your name" required></label><label class="field">Phone number<input name="phone" placeholder="+256 700 000 000" required></label><label class="field">Farm / business name<input name="farm" placeholder="Your farm name"></label><label class="field">Farm type<select name="farmType"><option>Black Soldier Fly (BSF)</option><option>Other livestock</option></select></label><label class="field full">Farm location<input name="location" placeholder="District, region" required></label><div class="field full"><button class="btn btn-primary btn-block">Create account ${icon('arrow_forward')}</button></div></div></form>`);m.querySelector('#signup-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target),photo=await (e.target.elements.photo.files[0]?compressAvatar(e.target.elements.photo.files[0]):null);db.role='farmer';db.user={name:f.get('name'),title:`BSF farmer · ${f.get('location')||'New member'}`,avatar:'👩🏽‍🌾',photo,phone:f.get('phone'),farm:f.get('farm'),farmType:f.get('farmType'),location:f.get('location')};save();m.remove();go('home');toast('Your farmer account is ready!')};}
function compressAvatar(file){return new Promise(resolve=>{const reader=new FileReader();reader.onerror=()=>resolve(null);reader.onload=()=>{const img=new Image();img.onerror=()=>resolve(null);img.onload=()=>{const scale=Math.min(1,320/Math.max(img.width,img.height)),canvas=document.createElement('canvas');canvas.width=Math.round(img.width*scale);canvas.height=Math.round(img.height*scale);canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',.82))};img.src=reader.result};reader.readAsDataURL(file)})}
app.addEventListener('click',e=>{let el=e.target.closest('[data-onboarding-dot],[data-onboarding],[data-product-qty],[data-favorite],[data-order-filter],[data-promo-index],[data-home-result],[data-go],[data-filter],[data-set-filter],[data-add],[data-qty],[data-remove],[data-edit],[data-action],[data-order-status]');if(!el)return;if(el.dataset.onboardingDot!==undefined){onboardingStep=Number(el.dataset.onboardingDot);renderOnboarding();return}if(el.dataset.onboarding==='skip'){finishOnboarding();return}if(el.dataset.onboarding==='back'){onboardingStep=Math.max(0,onboardingStep-1);renderOnboarding();return}if(el.dataset.onboarding==='next'){if(onboardingStep<onboardingSlides.length-1){onboardingStep++;renderOnboarding()}else finishOnboarding();return}if(el.dataset.favorite){const id=el.dataset.favorite;db.favorites.includes(id)?db.favorites=db.favorites.filter(x=>x!==id):db.favorites.push(id);save();render();toast(db.favorites.includes(id)?'Added to favorites':'Removed from favorites');return}if(el.dataset.productQty){const input=$('#product-qty');if(input)input.value=Math.max(1,(Number(input.value)||1)+(el.dataset.productQty==='inc'?1:-1));return}if(el.dataset.orderFilter){orderFilter=el.dataset.orderFilter;render();return}if(el.dataset.promoIndex!==undefined){const root=document.querySelector('.farmer-promo');if(root){const idx=Number(el.dataset.promoIndex);root.querySelectorAll('[data-promo-slide]').forEach((x,n)=>{x.classList.toggle('active',n===idx);x.setAttribute('aria-hidden',n===idx?'false':'true')});root.querySelectorAll('[data-promo-index]').forEach((x,n)=>{x.classList.toggle('active',n===idx);x.setAttribute('aria-current',n===idx?'true':'false')})}return}if(el.dataset.homeResult){let item=db.inventory.find(w=>w.id===el.dataset.homeResult);search=item?.name||'';filter='All';go(item?`product/${item.id}`:'market');return}if(el.dataset.go){go(el.dataset.go);return}if(el.dataset.filter){filter=el.dataset.filter;render();return}if(el.dataset.setFilter){filter=el.dataset.setFilter;search='';if(route()==='category')render();else render();return}if(el.dataset.add){const amount=Math.max(1,Number($('#product-qty')?.value||el.dataset.addQty)||1);let x=db.cart.find(c=>c.id===el.dataset.add);if(x)x.qty+=amount;else db.cart.push({id:el.dataset.add,qty:amount});save();toast('Added to your order');render();return}if(el.dataset.qty){let c=db.cart.find(x=>x.id===el.dataset.qty);if(c){c.qty+=+el.dataset.delta;if(c.qty<1)db.cart=db.cart.filter(x=>x.id!==c.id)}save();render();return}if(el.dataset.remove){db.cart=db.cart.filter(x=>x.id!==el.dataset.remove);save();render();return}if(el.dataset.edit){listingModal(el.dataset.edit);return}if(el.dataset.orderStatus){let o=db.orders.find(x=>x.id===el.dataset.orderStatus);if(o)advance(o);return}let a=el.dataset.action;if(a==='place-order')placeOrder();if(a==='clear-cart'){db.cart=[];save();render()}if(a==='new-listing')listingModal();if(a==='signup')signupModal();if(a==='logout'){db.role=null;db.user=null;save();go('login')}if(a==='menu')toast('Use the navigation tabs to move around the demo');if(a==='notifications')toast('You’re all caught up!');if(a==='help')openModal('We’re here to help',`<p>Our farmer support team is ready to help with supplies, orders, or deliveries.</p><div class="list-row"><div class="list-icon">${icon('call')}</div><div class="row-main"><strong>Call Green Divert</strong><small>+256 700 123 456 · Mon–Sat, 8am–6pm</small></div></div><div class="list-row"><div class="list-icon">${icon('mail')}</div><div class="row-main"><strong>Email our team</strong><small>hello@greendivert.africa</small></div></div>`);if(a==='forgot')openModal('Reset your password',`<p class="muted">Enter your phone number and we’ll help you get back in.</p><label class="field">Phone number<input placeholder="+256 700 123 456"></label><button class="btn btn-primary btn-block" style="margin-top:15px" data-action="reset-sent">Send reset code</button>`);if(a==='avatar')toast('Avatar picker is ready in the full account build');if(a==='save-profile'){const name=$('#profile-name')?.value.trim();if(name)db.user.name=name;save();render();toast('Your farm profile has been saved')}if(a==='invite-agent')openModal('Add a field agent',`<div class="form-grid"><label class="field">Agent name<input placeholder="Full name"></label><label class="field">Phone number<input placeholder="+256 700 000 000"></label><label class="field full">Assigned area<input placeholder="District or collection zone"></label><button class="btn btn-primary field full" data-action="invite-sent">Send invitation</button></div>`);if(a==='call-agent')toast('Call +256 700 123 456');if(a==='agent-history')openModal('Agent collection history',`<div class="list">${db.collections.map(c=>`<div class="list-row"><div class="list-icon">${icon('recycling')}</div><div class="row-main"><strong>${c.type} · ${c.qty} kg</strong><small>${c.agent} · ${c.place} · ${c.date}</small></div></div>`).join('')}</div>`);if(a==='export')toast('Inventory report prepared for this demo');if(a==='filters')openModal('Filter marketplace supplies',`<div class="list">${['All','Vegetable scraps','Fruit waste','Crop residues'].map(x=>`<button class="side-link" data-filter="${x}">${icon('filter_list')}${x}</button>`).join('')}</div>`);if(a==='sample-order')openModal('Sample order · GD-48291',`<div class="order-banner"><strong>David Kato · Wakiso</strong><span class="badge orange">Needs confirmation</span></div><p>4× Banana peels · 2× Vegetable mix<br><strong>UGX 350,000</strong></p><button class="btn btn-primary btn-block" data-action="sample-confirm">Confirm this sample order</button>`);});
function advance(o){let steps=['Order received','Confirmed','Preparing','On the way','Delivered'];o.progress=Math.min(4,(o.progress||0)+1);o.status=steps[o.progress];if(o.progress===1&&!o.stockDeducted){o.items.forEach(i=>{let w=db.inventory.find(x=>x.name===i.name);if(w)w.stock=Math.max(0,w.stock-i.qty*50)});o.stockDeducted=true}save();render();toast(`Order ${o.id} updated: ${o.status}`)}
app.addEventListener('submit',e=>{if(e.target.id==='login-form'){e.preventDefault();login('farmer')}if(e.target.id==='collection-form'){e.preventDefault();let f=new FormData(e.target),w=db.inventory.find(x=>x.id===f.get('type')),qty=+f.get('qty');if(f.get('quality').startsWith('Passed'))w.stock+=qty;let date=new Date().toLocaleString('en-UG',{weekday:'short',hour:'numeric',minute:'2-digit'});db.collections.unshift({id:'COL-'+Date.now().toString().slice(-4),type:w.name,qty,agent:f.get('agent'),place:f.get('place'),date,status:f.get('quality').startsWith('Passed')?'Added to stock':'Awaiting review'});save();render();toast(`Collection logged${f.get('quality').startsWith('Passed')?' and inventory updated':''}`)}});
app.addEventListener('input',e=>{if(e.target.id==='home-search'){search=e.target.value;let box=$('#home-search-results');if(box)box.innerHTML=homeSearchResults(search)}if(['market-search','market-search-mobile'].includes(e.target.id)){search=e.target.value;let pos=e.target.selectionStart;let items=db.inventory.filter(w=>(filter==='All'||w.category===filter)&&(`${w.name} ${w.category} ${w.location}`).toLowerCase().includes(search.toLowerCase()));let content=items.length?items.map(wasteCard).join(''):`<div class="empty card" style="grid-column:1/-1">No supplies match that search.</div>`;let grid=$('#market-grid');if(grid)grid.innerHTML=content;let mobileGrid=$('#market-grid-mobile');if(mobileGrid)mobileGrid.innerHTML=items.length?items.map(categoryProductCard).join(''):`<div class="category-empty"><strong>No matching supplies</strong><span>Try a different search or category.</span></div>`;e.target.focus();e.target.setSelectionRange(pos,pos)}if(e.target.id==='inventory-search'){let items=db.inventory.filter(w=>w.name.toLowerCase().includes(e.target.value.toLowerCase()));$('#inventory-body').innerHTML=inventoryRows(items)}});
app.addEventListener('change',e=>{if(e.target.id==='signup-photo-file'&&e.target.files[0]){const file=e.target.files[0],preview=$('#signup-photo-preview');if(file.type.startsWith('image/')&&preview){preview.innerHTML=`<img src="${URL.createObjectURL(file)}" alt="Selected profile photo">`}}});
app.addEventListener('change',e=>{if(['sort-select','sort-select-mobile'].includes(e.target.id)){ if(e.target.value==='price')db.inventory.sort((a,b)=>a.price-b.price);if(e.target.value==='stock')db.inventory.sort((a,b)=>b.stock-a.stock);render()}if(e.target.id==='stock-filter'){let items=db.inventory.filter(w=>e.target.value==='Low stock'?w.stock<250:e.target.value==='In stock'?w.stock>=250:true);$('#inventory-body').innerHTML=inventoryRows(items)}if(e.target.dataset.status){let o=db.orders.find(x=>x.id===e.target.dataset.status);if(o){o.status=e.target.value;o.progress=['Order received','Confirmed','Preparing','On the way','Delivered'].indexOf(o.status);if(o.progress===1&&!o.stockDeducted){o.items.forEach(i=>{let w=db.inventory.find(x=>x.name===i.name);if(w)w.stock=Math.max(0,w.stock-i.qty*50)});o.stockDeducted=true}save();render();toast(`Order ${o.id} updated`)}}});
window.startDemo=login;window.addEventListener('hashchange',render);if(!location.hash)history.replaceState(null,'','#'+(db.role==='staff'?'staff':db.role?'home':'login'));startExperience();
 
